/bin/zsh -lc "node <<'JS'
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const html=fs.readFileSync('index.html','utf8');
class Element {
 constructor(dataset={}){this.dataset=dataset;this.attrs={};this.handlers={};this.textContent='';this.value='';this.classes=new Set();this.classList={toggle:(name,on)=>on?this.classes.add(name):this.classes.delete(name)};}
 addEventListener(name,handler){this.handlers[name]=handler;}
 setAttribute(name,value){this.attrs[name]=value;}
 getAttribute(name){return this.attrs[name];}
 querySelector(){return this.child||(this.child=new Element());}
 focus(){this.focused=true;}
 showModal(){this.open=true;}
 close(){this.open=false;}
 emit(name,event={}){this.handlers[name]?.({target:this,preventDefault(){},...event});}
}
const ids=Object.fromEntries(['menu-toggle','main-nav','trial-email','selected-plan','form-note','notice-dialog','dialog-title','dialog-description','trial-form','dialog-done'].map(id=>[id,new Element()]));
ids['menu-toggle'].setAttribute('aria-expanded','false');ids['selected-plan'].value='Team';
const monthly=new Element({billing:'monthly'}),annual=new Element({billing:'annual'});
const team=new Element({monthly:'9',annual:'7'}),business=new Element({monthly:'16',annual:'13'});
const details=[new Element(),new Element()],trialLinks=[new Element({plan:'Free'}),new Element({plan:'Team'}),new Element({plan:'Business'}),new Element()];
const signin=[new Element(),new Element()];const docHandlers={};
const document={getElementById:id=>ids[id],querySelectorAll:selector=>({'[data-billing]':[monthly,annual],'[data-monthly]':[team,business],'[data-billing-detail]':details,'a[href=\"#start-trial\"]':trialLinks,'[data-sign-in]':signin}[selector]||[]),addEventListener:(name,handler)=>docHandlers[name]=handler};
vm.runInNewContext(html.match(/<script>([\\s\\S]*?)<\\/script>/)[1],{document,window:{matchMedia:()=>({matches:false,addEventListener(){}})}});
annual.emit('click');assert.equal(team.textContent,'"'$7'"');assert.equal(business.textContent,'"'$13'"');assert.equal(annual.attrs['aria-pressed'],'true');assert.equal(monthly.attrs['aria-pressed'],'false');assert(details.every(el=>el.textContent==='Billed annually'));
monthly.emit('click');assert.equal(team.textContent,'"'$9'"');assert.equal(business.textContent,'"'$16'"');assert(details.every(el=>el.textContent==='Billed monthly'));
ids['menu-toggle'].emit('click');assert.equal(ids['menu-toggle'].attrs['aria-expanded'],'true');assert(ids['main-nav'].classes.has('is-open'));
docHandlers.keydown({key:'Escape'});assert.equal(ids['menu-toggle'].attrs['aria-expanded'],'false');assert(ids['menu-toggle'].focused);
trialLinks[2].emit('click');assert.equal(ids['selected-plan'].value,'Business');assert(ids['trial-email'].focused);
ids['trial-form'].emit('submit');assert(ids['notice-dialog'].open);assert(ids['dialog-description'].textContent.includes('Business plan with monthly billing'));assert(ids['dialog-description'].textContent.includes('no account has been created'));
ids['dialog-done'].emit('click');assert("'!ids['"'notice-dialog'].open);
signin[0].emit('click');assert(ids['notice-dialog'].open);assert(ids['dialog-title'].textContent.includes('Welcome'));
trialLinks[0].emit('click');ids['trial-form'].emit('submit');assert(ids['dialog-description'].textContent.includes('Free plan.'));
assert(/type=\"email\"["'^>]*required/.test(html));
console.log('"'PASS: monthly/annual prices and labels, pressed states, mobile menu, Escape handling, plan selection, trial preview, sign-in preview, dialog dismissal, required email validation markup.');
JS"

